<script id="tt-navigation-enabled-script-20261007">
(() => {
  const header = document.querySelector('.tt-h');
  if (!header) return;
  const nav = header.querySelector('.tt-h__nav');
  const toggle = header.querySelector('.tt-h__toggle');
  const burger = header.querySelector('.tt-h__burger');
  const menus = [...nav.querySelectorAll('.tt-h__drop')];
  const fullMenu = window.matchMedia('(min-width:720px)');
  const wide = () => fullMenu.matches;
  const sync = () => {
    burger.setAttribute('aria-expanded', String(toggle.checked));
    burger.setAttribute('aria-label', toggle.checked ? 'Close menu' : 'Open menu');
    for (const menu of menus) {
      const button = menu.querySelector('.tt-h__chevron');
      button.setAttribute('aria-expanded', String(menu.open));
      button.setAttribute('aria-label', (menu.open ? 'Close ' : 'Open ') + menu.querySelector('.tt-h__parent').textContent.trim() + ' submenu');
    }
  };
  burger.setAttribute('role', 'button');
  burger.setAttribute('tabindex', '0');
  burger.addEventListener('keydown', event => {
    if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); toggle.checked = !toggle.checked; sync(); }
  });
  toggle.addEventListener('change', sync);
  for (const menu of menus) {
    menu.addEventListener('toggle', sync);
    menu.querySelector('.tt-h__chevron').addEventListener('click', event => {
      event.preventDefault(); event.stopPropagation(); const opening = !menu.open; menus.forEach(other => { if (other !== menu) other.open = false; }); menu.open = opening; sync();
    });
    menu.addEventListener('pointerenter', event => { if (wide() && event.pointerType === 'mouse') { menu.open = true; sync(); } });
    menu.addEventListener('pointerleave', event => { if (wide() && event.pointerType === 'mouse') { menu.open = false; sync(); } });
  }
  document.addEventListener('click', event => {
    if (!wide() && toggle.checked && !header.contains(event.target)) { toggle.checked = false; menus.forEach(m => m.open = false); sync(); }
  });
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') { toggle.checked = false; menus.forEach(m => m.open = false); sync(); }
  });
  const resetForMode = () => { toggle.checked = false; menus.forEach(menu => { menu.open = false; }); sync(); };
  if (fullMenu.addEventListener) fullMenu.addEventListener('change', resetForMode);
  else fullMenu.addListener(resetForMode);
